create table public.availability_windows(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,starts_at timestamptz not null,ends_at timestamptz not null,timezone text not null default 'Asia/Kolkata',recurrence_rule text,visibility text not null default 'matched_employers' check(visibility in ('private','matched_employers','organization')),created_at timestamptz not null default now(),check(ends_at>starts_at));
create table public.scheduled_events(id uuid primary key default gen_random_uuid(),event_type text not null check(event_type in ('interview','support','evidence_review','office_hours')),title text not null,starts_at timestamptz not null,ends_at timestamptz not null,timezone text not null,mode text not null check(mode in ('video','phone','in_person')),meeting_ref text,location text,status text not null default 'proposed' check(status in ('proposed','confirmed','reschedule_requested','cancelled','completed','no_show')),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),check(ends_at>starts_at));
create table public.event_participants(event_id uuid not null references public.scheduled_events(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null,response text not null default 'pending' check(response in ('pending','accepted','declined')),responded_at timestamptz,primary key(event_id,user_id));
alter table public.availability_windows enable row level security;alter table public.scheduled_events enable row level security;alter table public.event_participants enable row level security;create policy "users manage availability" on public.availability_windows for all using(user_id=auth.uid()) with check(user_id=auth.uid());create policy "participants read events" on public.scheduled_events for select using(created_by=auth.uid() or exists(select 1 from public.event_participants p where p.event_id=id and p.user_id=auth.uid()));create policy "participants read event membership" on public.event_participants for select using(user_id=auth.uid() or exists(select 1 from public.scheduled_events e where e.id=event_id and e.created_by=auth.uid()));create index scheduled_events_time_idx on public.scheduled_events(starts_at,status);
